module tb_top; reg clk; reg rst_n; reg [7:0] din; reg wr_en; reg rd_en; wire [7:0] dout; wire full; wire empty; integer i; integer err; top #(.DEPTH(16), .WIDTH(8)) uut (.clk(clk), .rst_n(rst_n), .din(din), .wr_en(wr_en), .rd_en(rd_en), .dout(dout), .full(full), .empty(empty)); initial begin clk = 0; forever #5 clk = ~clk; end initial begin rst_n = 0; din = 0; wr_en = 0; rd_en = 0; #10 rst_n = 1; #10; // Write 16 words err = 0; for (i=0; i<16; i=i+1) begin @(posedge clk); wr_en = 1; din = i; @(posedge clk); wr_en = 0; end #10; // Read 16 words for (i=0; i<16; i=i+1) begin @(posedge clk); rd_en = 1; @(posedge clk); if (dout !== i) err = err + 1; rd_en = 0; end #10; if (err == 0) $display("TEST_PASS"); else $display("TEST_FAILED with %d errors", err); #20 $finish; end endmodule
